    # 2026-08-11:两条都从**进行时**改成**状态**。
    # 理由不是措辞,是这块屏**分不出自己在哪个状态** —— 它拿不到盒子的 outbox,
    # `waiting` / `exhausted` / `refused` 在它眼里一模一样,于是「结算中」是无条件说出口的。
    # 被云端永久拒收的那一局,屏上会永远写着「结算中」。
    # 判据:**一块屏分不出自己在哪个状态时,它只能说在所有状态下都为真的那句话。**
    # 「还没送到云端」在三种状态下都为真;「结算中」只在其中一种为真。
